import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.QWVCgkrI.js";const i="/study/images/os/cancelling-overlapped-io.svg",h=JSON.parse('{"title":"Windowsの非同期I/Oをキャンセルする — 要求・完了・解放","description":"","frontmatter":{"title":"Windowsの非同期I/Oをキャンセルする — 要求・完了・解放","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"CancelIoExで指定した要求を中止する仕組みを追い、通常完了との競合、タイムアウト、IOCPで完了を回収してからバッファを解放する手順を解説する。","aliases":["CancelIoEx","CancelIo","overlapped I/O cancellation","非同期I/Oのキャンセル","ERROR_NOT_FOUND","ERROR_OPERATION_ABORTED","キャンセル競合","完了回収"],"verification":"Microsoft LearnのキャンセルとI/O完了ポートの資料に照合（2026-11-06）"}},"headers":[],"relativePath":"os/cancelling-overlapped-io.md","filePath":"os/cancelling-overlapped-io.md"}'),n={name:"os/cancelling-overlapped-io.md"};function s(c,e,l,d,p,f){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="windowsの非同期i-oをキャンセルする-—-要求・完了・解放" tabindex="-1">Windowsの非同期I/Oをキャンセルする — 要求・完了・解放 <a class="header-anchor" href="#windowsの非同期i-oをキャンセルする-—-要求・完了・解放" aria-label="Permalink to &quot;Windowsの非同期I/Oをキャンセルする — 要求・完了・解放&quot;">​</a></h1><p>ゲームで次のシーンのアセットを先読みしている途中に、プレイヤーがタイトル画面へ戻ったとします。ローダーは読み取りのキャンセルを依頼できます。<strong>依頼のあとも、読み取りが終わるまではOSがバッファを使う可能性があります。</strong> ここではWindowsの<code>OVERLAPPED</code>を使うファイル読み取りを対象に、キャンセルの依頼と結果の回収を追います。<a href="/study/os/asynchronous-file-io.html">非同期I/Oの基礎</a> · <a href="/study/game/asset-loading.html">ゲームのアセット読み込み</a></p><h2 id="cancelioexは処理中の要求を探す" tabindex="-1">CancelIoExは処理中の要求を探す <a class="header-anchor" href="#cancelioexは処理中の要求を探す" aria-label="Permalink to &quot;CancelIoExは処理中の要求を探す&quot;">​</a></h2><p><code>CancelIoEx(file, &amp;request.overlapped)</code>は、現在のプロセスがそのハンドルに出したI/Oから、指定した<code>OVERLAPPED</code>に対応する要求を探し、キャンセルを依頼します。<code>CancelIoEx(file, nullptr)</code>はそのハンドルに対する同じプロセスの未完了I/O全体を対象にします。どちらも、呼び出すスレッドとI/Oを発行したスレッドが異なっていても使えます。<code>CancelIo(file)</code>は、呼び出したスレッド自身がそのハンドルに出した未完了のI/Oを対象にします。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelioex" target="_blank" rel="noreferrer">Microsoft: CancelIoEx</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelio" target="_blank" rel="noreferrer">Microsoft: CancelIo</a></p><p><code>CancelIoEx</code>の成功は対象のI/Oにキャンセルを要求できたことを示します。実際にキャンセルできるかどうかは、ドライバーの対応とI/Oの進み具合に依存します。<code>FALSE</code>で戻った場合は、直後の<code>GetLastError()</code>でキャンセル呼び出し自体のエラーを読みます。<code>ERROR_NOT_FOUND</code>は、要求時にキャンセル対象が見つからなかったことを示します。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/canceling-pending-i-o-operations" target="_blank" rel="noreferrer">Microsoft: Canceling Pending I/O Operations</a></p><figure class="study-figure"><img src="'+i+'" alt="読み取りを発行した後、キャンセルを要求できる。最終結果は通常完了、ERROR_OPERATION_ABORTED、別のI/Oエラーのいずれか。OVERLAPPEDとバッファは、発行からI/O完了通知の回収とアプリでの処理が終わるまで確保しておく。" width="760" height="565" loading="lazy"><figcaption>キャンセル要求後に起こり得る三つの完了結果。<a href="/study/images/os/cancelling-overlapped-io.svg" target="_blank" rel="noopener noreferrer">キャンセルと完了の図を拡大</a></figcaption></figure><h2 id="最終結果は読み取り側の完了から知る" tabindex="-1">最終結果は読み取り側の完了から知る <a class="header-anchor" href="#最終結果は読み取り側の完了から知る" aria-label="Permalink to &quot;最終結果は読み取り側の完了から知る&quot;">​</a></h2><p>完了通知を省略しないI/O完了ポート（IOCP）では、発行時に成功したか<code>ERROR_IO_PENDING</code>になった読み取りは、完了パケットで結果を回収します。<code>GetQueuedCompletionStatus</code>が<code>FALSE</code>を返しても、返された<code>OVERLAPPED*</code>が<code>nullptr</code>以外なら、対応するI/Oの失敗を受け取っています。このときの<code>GetLastError()</code>が、以下の表の読み取りのエラーです。<a href="/study/os/io-completion-ports.html">I/O完了ポートの仕組み</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatus</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelioex#remarks" target="_blank" rel="noreferrer">Microsoft: CancelIoExの完了状態</a></p><table tabindex="0"><thead><tr><th>回収したI/Oの結果</th><th>ローダーの扱い</th></tr></thead><tbody><tr><td>正常完了</td><td>まだ必要な読み取りなら転送数を確認して使う。シーン遷移などで不要なら結果を捨てる。</td></tr><tr><td><code>ERROR_OPERATION_ABORTED</code></td><td>I/Oがキャンセルされて終わった。読み取り結果は使わず、要求を片付ける。</td></tr><tr><td>別のエラー</td><td>読み取りの失敗として扱い、エラーコードに応じて記録や復旧を行う。</td></tr></tbody></table><p>例えば、読み取りAの完了パケットがキューに入り、ワーカーはまだ取り出していないとします。この時点で別のスレッドがAを<code>CancelIoEx</code>で指定すると、既にI/O自体が終わっているため、<code>ERROR_NOT_FOUND</code>が返ることがあります。ワーカーはその後もAの完了を取り出します。キャンセルを要求できた場合でも、通常の読み取りが先に完了することがあります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelioex" target="_blank" rel="noreferrer">Microsoft: CancelIoExの戻り値と完了状態</a></p><p>イベント方式では、要求に対応するイベントと<code>GetOverlappedResult</code>で最終結果を受け取ります。IOCP方式では、完了パケットに入っているアドレスをワーカーが要求の特定に使うため、アプリ側の要求管理はパケットを回収するまで続きます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getoverlappedresult" target="_blank" rel="noreferrer">Microsoft: GetOverlappedResult</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus#parameters" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatusのlpOverlapped</a></p><h2 id="タイムアウトの後も要求を持つ" tabindex="-1">タイムアウトの後も要求を持つ <a class="header-anchor" href="#タイムアウトの後も要求を持つ" aria-label="Permalink to &quot;タイムアウトの後も要求を持つ&quot;">​</a></h2><p><code>GetQueuedCompletionStatus</code>で指定した待ち時間を超えると、<code>FALSE</code>、<code>OVERLAPPED* == nullptr</code>、<code>WAIT_TIMEOUT</code>を受け取ります。これはその呼び出しが完了パケットを受け取れなかったという結果です。どのI/Oに対してキャンセルを依頼するかは、要求ごとの期限を追っているアプリが決めます。例えば、シーンの切り替えを先に進める場合は、I/Oの要求管理側がバッファと<code>OVERLAPPED</code>の所有を引き継ぎ、後で完了を回収します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus#parameters" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatusの待機時間</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile#parameters" target="_blank" rel="noreferrer">Microsoft: ReadFileのバッファの有効期間</a></p><p><code>OVERLAPPED</code>とバッファを要求オブジェクトにまとめ、保留中の要求をアプリで登録しておくと、所有権を追いやすくなります。ワーカーが完了を処理する一方で別スレッドがキャンセルを呼ぶ設計では、キャンセル側も呼び出しが戻るまで要求を有効に保ちます。アドレスを別の要求に使い回すと、古い完了を別の要求のものとして扱ったり、遅れて実行したキャンセルが新しい要求を指したりします。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/canceling-pending-i-o-operations#cancellation-considerations" target="_blank" rel="noreferrer">Microsoft: キャンセル時の競合と構造体の再利用</a></p><h2 id="終了時は発行を止め、完了を回収してからワーカーを止める" tabindex="-1">終了時は発行を止め、完了を回収してからワーカーを止める <a class="header-anchor" href="#終了時は発行を止め、完了を回収してからワーカーを止める" aria-label="Permalink to &quot;終了時は発行を止め、完了を回収してからワーカーを止める&quot;">​</a></h2><p>以下は、開始時点で成功した<code>ReadFile</code>も含めて、受理されたI/Oの完了パケットを回収するIOCP構成の例です。即時成功時の通知を省略する設定や、要求ごとに通知を抑止する設定を使う場合は、各要求をどの経路で完了処理するかに合わせて管理します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-setfilecompletionnotificationmodes" target="_blank" rel="noreferrer">Microsoft: SetFileCompletionNotificationModes</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getqueuedcompletionstatus#parameters" target="_blank" rel="noreferrer">Microsoft: GetQueuedCompletionStatusの通知抑止</a></p><ol><li><strong>新規発行を止める。</strong> 終了状態へ切り替え、既に発行処理に入ったスレッドが結果を登録し終えるのを待ちます。発行側が止まる前に全体キャンセルを依頼すると、その後に新しい要求が加わることがあります。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/canceling-pending-i-o-operations#cancellation-considerations" target="_blank" rel="noreferrer">Microsoft: キャンセル時の競合</a></li><li><strong>未回収の要求にキャンセルを依頼する。</strong> ハンドルと要求の情報を保持したまま<code>CancelIoEx</code>を呼びます。キャンセル呼び出しの戻り値で未回収件数を減らす処理は行わず、完了処理の側で要求を管理します。</li><li><strong>ワーカーを動かしたまま、残りの完了を回収する。</strong> 通常完了・中止・エラーをそれぞれ片付け、完了処理とキャンセル処理の双方が要求を使い終えたらバッファや構造体を解放します。終了を待つ側が、完了処理にも必要なロックを保持したまま待つと、ワーカーが進めなくなります。</li><li><strong>ワーカーを終了してハンドルを閉じる。</strong> 例えば<code>PostQueuedCompletionStatus</code>でI/Oとは区別できる終了用パケットをワーカーの数だけ送り、全ワーカーの終了を待ってからファイルと完了ポートを閉じます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-postqueuedcompletionstatus" target="_blank" rel="noreferrer">Microsoft: PostQueuedCompletionStatus</a></li></ol><h2 id="完了パケットを観察する実践" tabindex="-1">完了パケットを観察する実践 <a class="header-anchor" href="#完了パケットを観察する実践" aria-label="Permalink to &quot;完了パケットを観察する実践&quot;">​</a></h2><p>C++の実践では、自分の実行ファイルに読み取りを発行し、どの<code>OVERLAPPED</code>が完了として返ったかを表示します。そこで使う完了回収が、キャンセルを組み込む場合にも要求の寿命を決める基準になります。<a href="/study/practice/io/iocp-observation.html">C++でIOCPの完了を観察する</a></p>',19)])])}const m=o(n,[["render",s]]);export{h as __pageData,m as default};
